        _setLaunchV2Dependencies(coordinator_,tokenFactory_,hook_,buybackExecutor_,aggregator_);
        emit LaunchV2DependenciesRotated(coordinator_,tokenFactory_,hook_,buybackExecutor_,aggregator_);
